import {
  Mjml,
  MjmlBody,
  MjmlColumn,
  MjmlFont,
  MjmlHead,
  MjmlImage,
  MjmlPreview,
  MjmlSection,
  MjmlSpacer,
  MjmlText,
  MjmlWrapper,
} from "@faire/mjml-react";
import type { ReactNode } from "react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

type BentoPaddedVariant =
  | "padded-left"
  | "padded-right"
  | "padded-sides"
  | "padded-full"
  | "padded-left-reverse"
  | "padded-right-reverse"
  | "padded-sides-reverse"
  | "padded-full-reverse";

const colors = {
  border: "#d1d5db",
  canvas: "#f1f5f9",
  dark: "#030712",
  light: "#f3f4f6",
  muted: "#6b7280",
  mutedDark: "#d1d5db",
  subtle: "#9ca3af",
  surface: "#fffffe",
  surfaceMuted: "#f9fafb",
  white: "#fffffe",
} as const;

const fontFamily =
  "Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, sans-serif";

interface BentoEmailShellProps {
  children: ReactNode;
  preview: string;
  theme: EmailTheme;
}

const BentoEmailShell = ({
  children,
  preview,
  theme,
}: BentoEmailShellProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>{preview}</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody backgroundColor={colors.canvas} width={theme.containerWidth}>
      <MjmlWrapper backgroundColor={colors.surface} padding="44px 24px">
        {children}
      </MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

const VerticalGap = () => (
  <MjmlSection padding="0">
    <MjmlColumn padding="0">
      <MjmlSpacer height="24px" />
    </MjmlColumn>
  </MjmlSection>
);

interface BentoImageCardItem {
  description?: string;
  imageAlt: string;
  imageSrc: string;
  title: string;
}

interface ProductTileData extends BentoImageCardItem {
  price: string;
}

const ProductTile = ({
  dark = false,
  item,
  padding,
  width,
}: {
  dark?: boolean;
  imageInsetOverride?: 16 | 32;
  item: ProductTileData;
  padding: "full" | "left" | "right" | "sides";
  width: 168 | 264 | 360;
}) => {
  const imagePadding = {
    full: "16px",
    left: "16px 0 0 16px",
    right: "16px 16px 0 0",
    sides: "16px 16px 0",
  }[padding];
  return (
    <MjmlColumn
      backgroundColor={dark ? colors.dark : colors.light}
      borderRadius="8px"
      padding="0"
      verticalAlign="top"
      width={`${width}px`}
    >
      <MjmlText
        color={dark ? colors.white : colors.dark}
        fontFamily={fontFamily}
        fontSize="14px"
        fontWeight="600"
        lineHeight="20px"
        padding="16px 16px 0"
      >
        {item.title} · {item.price}
      </MjmlText>
      {(() => {
        if (item.description) {
          return (
            <MjmlText
              color={dark ? colors.subtle : colors.muted}
              fontFamily={fontFamily}
              fontSize="12px"
              lineHeight="16px"
              padding="12px 16px 0"
            >
              {item.description}
            </MjmlText>
          );
        }
        return null;
      })()}
      <MjmlImage
        alt={item.imageAlt}
        borderRadius="8px"
        padding={imagePadding}
        src={item.imageSrc}
      />
    </MjmlColumn>
  );
};

const ProductRow = ({
  darkIndexes,
  items,
  padding,
  widths,
}: {
  darkIndexes: readonly number[];
  items: readonly ProductTileData[];
  padding: "full" | "left" | "right" | "sides";
  widths: readonly (168 | 264 | 360)[];
}) => (
  <MjmlSection padding="0">
    {items.map((item, index) => (
      <ProductTile
        dark={darkIndexes.includes(index)}
        item={item}
        key={`${item.title}-${index}`}
        padding={padding}
        width={widths[index]}
      />
    ))}
  </MjmlSection>
);

const TwoRowsThreeColumnsSection = ({
  bottom,
  top,
  variant,
}: {
  bottom: readonly [ProductTileData, ProductTileData, ProductTileData];
  top: readonly [ProductTileData, ProductTileData];
  variant: BentoPaddedVariant;
}) => {
  const padding = variant.replace("padded-", "").replace("-reverse", "") as
    | "full"
    | "left"
    | "right"
    | "sides";
  const reverse = variant.endsWith("reverse");
  const topRow = (
    <ProductRow
      darkIndexes={[0]}
      items={top}
      padding={padding}
      widths={[264, 264]}
    />
  );
  const bottomRow = (
    <ProductRow
      darkIndexes={[1]}
      items={bottom}
      padding={padding}
      widths={[168, 168, 168]}
    />
  );
  return (
    <>
      {reverse ? bottomRow : topRow}
      <VerticalGap />
      {reverse ? topRow : bottomRow}
    </>
  );
};

const EvenSplitTwoThirdsSection = ({
  bottom,
  top,
  variant,
}: {
  bottom: readonly [ProductTileData, ProductTileData];
  top: readonly [ProductTileData, ProductTileData];
  variant: BentoPaddedVariant;
}) => {
  const padding = variant.replace("padded-", "").replace("-reverse", "") as
    | "full"
    | "left"
    | "right"
    | "sides";
  const reverse = variant.endsWith("reverse");
  const topRow = (
    <ProductRow
      darkIndexes={[0]}
      items={top}
      padding={padding}
      widths={[264, 264]}
    />
  );
  const bottomRow = (
    <ProductRow
      darkIndexes={[1]}
      items={bottom}
      padding={padding}
      widths={[168, 360]}
    />
  );
  return (
    <>
      {reverse ? bottomRow : topRow}
      <VerticalGap />
      {reverse ? topRow : bottomRow}
    </>
  );
};

type ProductPair = readonly [ProductTileData, ProductTileData];

type ProductTriple = readonly [
  ProductTileData,
  ProductTileData,
  ProductTileData,
];

type BentoProductGridStyle = "full" | "left" | "right" | "sides";

type BentoProductGridPlacement = "normal" | "reverse";

type InternalBentoProductGridProps =
  | {
      data?: {
        bottom: ProductTriple;
        top: ProductPair;
      };
      placement?: BentoProductGridPlacement;
      style?: BentoProductGridStyle;
      variant?: "two-row-three-column";
    }
  | {
      data?: {
        bottom: ProductPair;
        top: ProductPair;
      };
      placement?: BentoProductGridPlacement;
      style?: BentoProductGridStyle;
      variant: "even-split-two-thirds";
    };

const product = (
  image: string,
  title: string,
  price: string,
  description?: string
): ProductTileData => ({
  description,
  imageAlt: title,
  imageSrc: emailAsset(`bento-grids/${image}.jpg`),
  price,
  title,
});

const productTop: ProductPair = [
  product(
    "4-bento-lg-1",
    "iPhone 17",
    "/ from $1099",
    "Innovative design for ultimate\nperformance and battery life."
  ),
  product(
    "4-bento-lg-2",
    "MacBook Air",
    "/ from $999",
    "Strikingly thin and fast so you can\nwork, play, or create anywhere."
  ),
];

const productBottom: ProductTriple = [
  product("4-bento-sm-1", "Watch Ultra", "/ from $799"),
  product("4-bento-sm-2", "Mac Mini", "/ from $599"),
  product("4-bento-sm-3", "AirPods", "/ from $129"),
];

const toPaddedVariant = (
  style: BentoProductGridStyle,
  placement: BentoProductGridPlacement
): BentoPaddedVariant => {
  const reverse = placement === "reverse" ? "-reverse" : "";
  return `padded-${style}${reverse}` as BentoPaddedVariant;
};

const splitProductBottom = (variant: BentoPaddedVariant): ProductPair => {
  const insetOnBothSides =
    variant.includes("sides") || variant.includes("full");
  const reverse = variant.endsWith("reverse");
  return [
    product(
      `4-bento-sm-${insetOnBothSides ? "5" : "4"}`,
      "Watch Ultra",
      "/ from $799"
    ),
    product(
      `4-bento-lg-${insetOnBothSides ? "4" : "3"}`,
      reverse ? "Mac Mini" : "Watch Ultra",
      reverse ? "/ from $599" : "/ from $799"
    ),
  ];
};

const TwoRowProductGrid = (
  props: Extract<
    InternalBentoProductGridProps,
    {
      variant?: "two-row-three-column";
    }
  >
) => {
  const style = props.style ?? "full";
  const placement = props.placement ?? "normal";
  const variant = toPaddedVariant(style, placement);
  return (
    <TwoRowsThreeColumnsSection
      bottom={props.data?.bottom ?? productBottom}
      top={props.data?.top ?? productTop}
      variant={variant}
    />
  );
};

const SplitProductGrid = (
  props: Extract<
    InternalBentoProductGridProps,
    {
      variant: "even-split-two-thirds";
    }
  >
) => {
  const style = props.style ?? "left";
  const placement = props.placement ?? "normal";
  const variant = toPaddedVariant(style, placement);
  return (
    <EvenSplitTwoThirdsSection
      bottom={props.data?.bottom ?? splitProductBottom(variant)}
      top={props.data?.top ?? productTop}
      variant={variant}
    />
  );
};

const BentoProductGridSection = (props: InternalBentoProductGridProps) =>
  props.variant === "even-split-two-thirds" ? (
    <SplitProductGrid {...props} />
  ) : (
    <TwoRowProductGrid {...props} />
  );

export type BentoProductGridProps = InternalBentoProductGridProps & {
  theme?: typeof defaultTheme;
};

export const BentoProductGrid = ({
  theme = defaultTheme,
  ...props
}: BentoProductGridProps) => (
  <BentoEmailShell preview="Flexible bento product grid" theme={theme}>
    <BentoProductGridSection {...props} />
  </BentoEmailShell>
);

BentoProductGrid.PreviewProps = {
  placement: "normal",
  style: "full",
  variant: "two-row-three-column",
} satisfies BentoProductGridProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
